use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts whole seconds since the Unix epoch into a `YYYY-MM-DD` UTC date.
/// The year is clamped to 0..=9999 so the output is always exactly 10 characters.
fn format_date(unix_seconds: u64) -> String {
    let days = unix_seconds / 86_400;

    // Civil-from-days (H. Hinnant's algorithm), proleptic Gregorian calendar.
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }

    if y > 9_999 {
        y = 9_999;
    }

    format!("{:04}-{:02}-{:02}", y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        RunInfo {
            date: format_date(now.seconds),
            started: now.seconds,
        }
    }
}

export!(Node);
